<?php use App\Services\Analytics as A; require __DIR__ . '/_head.php'; ?>
<div class="alert alert-light border small">
  <strong>Formulas.</strong> <em>Booking rate</em> (telephone, social DM) = interactions that ended in a requested or confirmed appointment &divide; interactions with a recorded booking outcome (not booked + requested + confirmed). <em>Service-use rate</em> (reception only) = &ldquo;used&rdquo; &divide; (used + not used); &ldquo;unknown&rdquo; is shown separately and excluded. Reception does not book appointments, so no reception booking rate exists. A rate is <em>n/a</em> when its denominator is 0.
</div>
<div class="row g-3 mb-3">
  <div class="col-lg-5"><div class="card h-100"><div class="card-header bg-white fw-semibold">Interactions by channel</div><div class="card-body"><?= chart_canvas(['type' => 'bar', 'labels' => array_values($channelLabels), 'datasets' => [['label' => 'Interactions', 'data' => array_map(static fn ($c) => $c['interactions'], array_values($ch))], ['label' => 'Distinct customers', 'data' => array_map(static fn ($c) => $c['customers'], array_values($ch)), 'color' => '#7aa5e6']]], 'Interactions and distinct customers by channel', 280) ?></div></div></div>
  <div class="col-lg-7"><div class="card h-100"><div class="card-header bg-white fw-semibold">Interactions over time by channel</div><div class="card-body"><?= chart_canvas(['type' => 'bar', 'stacked' => true, 'labels' => $series['labels'], 'datasets' => [
    ['label' => 'Reception', 'data' => $series['channels']['reception'], 'color' => '#173b77'], ['label' => 'Telephone', 'data' => $series['channels']['phone'], 'color' => '#3b6fc4'], ['label' => 'Social DM', 'data' => $series['channels']['social_dm'], 'color' => '#a9c4ee']]], 'Interactions over time by channel', 280) ?></div></div></div>
</div>
<div class="card mb-3"><div class="card-header bg-white fw-semibold">Outcomes by channel</div><div class="table-responsive"><table class="table table-sm align-middle mb-0">
  <thead><tr><th>Channel</th><th class="text-end">Interactions</th><th class="text-end">Distinct customers</th><th class="text-end">Not booked</th><th class="text-end">Requested</th><th class="text-end">Confirmed</th><th class="text-end">Booking rate</th><th class="text-end">Used</th><th class="text-end">Not used</th><th class="text-end">Unknown</th><th class="text-end">Service-use rate</th></tr></thead><tbody>
  <?php foreach ($ch as $k => $v): $rec = $k === 'reception'; ?><tr><td><?= e($channelLabels[$k]) ?></td><td class="text-end"><?= (int) $v['interactions'] ?></td><td class="text-end"><?= (int) $v['customers'] ?></td>
    <?php if ($rec): ?><td class="text-end text-secondary" colspan="4">not applicable (reception does not book)</td><?php else: ?>
    <td class="text-end"><?= (int) $v['not_booked'] ?></td><td class="text-end"><?= (int) $v['requested'] ?></td><td class="text-end"><?= (int) $v['confirmed'] ?></td><td class="text-end"><?= e(pct($v['booking_rate'])) ?> <span class="text-secondary small">(<?= (int) ($v['requested'] + $v['confirmed']) ?>/<?= (int) $v['booking_decided'] ?>)</span></td><?php endif; ?>
    <?php if ($rec): ?><td class="text-end"><?= (int) $v['used'] ?></td><td class="text-end"><?= (int) $v['not_used'] ?></td><td class="text-end"><?= (int) $v['unknown'] ?></td><td class="text-end"><?= e(pct($v['usage_rate'])) ?> <span class="text-secondary small">(<?= (int) $v['used'] ?>/<?= (int) $v['usage_decided'] ?>)</span></td>
    <?php else: ?><td class="text-end text-secondary" colspan="4">not applicable (no service-use outcome)</td><?php endif; ?></tr><?php endforeach; ?>
  </tbody></table></div></div>
<div class="card"><div class="card-header bg-white fw-semibold">Appointments booked in the period, by originating channel (current status)</div><div class="table-responsive"><table class="table table-sm align-middle mb-0">
  <thead><tr><th>Channel</th><th class="text-end">Appointments</th><th class="text-end">Open (requested + confirmed)</th><th class="text-end">Completed</th><th class="text-end">Cancelled</th><th class="text-end">No-show</th><th class="text-end">Completion rate</th></tr></thead><tbody>
  <?php foreach ($appts as $k => $s): $t = array_sum($s); if ($k === 'none' && $t === 0) { continue; } $o = A::outcomeRates($s); ?><tr><td><?= e($k === 'none' ? 'No originating interaction' : $channelLabels[$k]) ?></td><td class="text-end"><?= (int) $t ?></td><td class="text-end"><?= (int) $o['open'] ?></td><td class="text-end"><?= (int) $s['completed'] ?></td><td class="text-end"><?= (int) $s['cancelled'] ?></td><td class="text-end"><?= (int) $s['no_show'] ?></td><td class="text-end"><?= e(pct($o['completion'])) ?> <span class="text-secondary small">(<?= (int) $s['completed'] ?>/<?= (int) $o['closed'] ?>)</span></td></tr><?php endforeach; ?>
  </tbody></table></div><div class="card-footer bg-white small text-secondary">Each appointment is counted once, under the channel of the interaction that created it. Completion rate = completed &divide; (completed + cancelled + no-show). Reception shows no appointments because it does not create them.</div></div>
